#ifndef SHOWAI_BOUNDARY_POLYNOMIAL_HPP
#define SHOWAI_BOUNDARY_POLYNOMIAL_HPP
#include "vector.hpp"
#include "record.hpp"
namespace showai_boundary {
using Q=Rational;
struct PolynomialBudget {uint64_t operations=0,max_operations=5000000;};
struct PolynomialContext {Context numbers;PolynomialBudget polynomial;bool step(){if(numbers.status!=SA_INK_OK)return false;if(polynomial.operations>=polynomial.max_operations){numbers.fail(SA_INK_CAPACITY);return false;}++polynomial.operations;return true;}};
class Polynomial {
    Pointer<PolynomialContext>ctx_;
public:
    Vector<Q>coefficients;
    Polynomial()=default;explicit Polynomial(PolynomialContext&c):ctx_(&c),coefficients(c.numbers){}
    Polynomial(PolynomialContext&c,const Q&q):ctx_(&c),coefficients(c.numbers){if(!q.zero())coefficients.push_back(q.owned(c.numbers));trim();}
    PolynomialContext*owner()const{return ctx_;}Context*context()const{return ctx_?&ctx_->numbers:nullptr;}
    bool valid()const{return !ctx_||ctx_->numbers.status==SA_INK_OK;}int degree()const{return(int)coefficients.size()-1;}bool zero()const{return coefficients.empty();}
    Q operator[](int i)const{return i>=0&&(uint32_t)i<coefficients.size()?coefficients[(uint32_t)i]:Q();}
    void trim(){while(!coefficients.empty()&&coefficients.back().zero()&&valid())coefficients.pop_back();if(coefficients.size()>65){if(ctx_)ctx_->numbers.fail(SA_INK_CAPACITY);return;}for(const auto&q:coefficients)if(!q.stored()){if(ctx_)ctx_->numbers.fail(SA_INK_CAPACITY);return;}}
    static Polynomial scalar(PolynomialContext&c,int64_t n){return Polynomial(c,Q::from_signed(c.numbers,n));}
};
inline PolynomialContext*poly_owner(const Polynomial&a,const Polynomial&b){if(a.owner()&&b.owner()&&a.owner()!=b.owner()){a.context()->fail(SA_INK_INVALID);return a.owner();}return a.owner()?a.owner():b.owner();}
inline Polynomial operator+(const Polynomial&a,const Polynomial&b){auto*c=poly_owner(a,b);if(!c)return Polynomial();Polynomial r(*c);if(!c->step())return r;uint32_t n=a.coefficients.size()>b.coefficients.size()?a.coefficients.size():b.coefficients.size();r.coefficients.resize(n);for(uint32_t i=0;i<n&&r.valid();i++)r.coefficients[i]=a[(int)i]+b[(int)i];r.trim();return r;}
inline Polynomial operator-(const Polynomial&a){if(!a.owner())return Polynomial();Polynomial r(*a.owner());if(!a.owner()->step())return r;for(const auto&q:a.coefficients)r.coefficients.push_back(-q);return r;}
inline Polynomial operator-(const Polynomial&a,const Polynomial&b){return a+(-b);}
inline Polynomial operator*(const Polynomial&a,const Polynomial&b){auto*c=poly_owner(a,b);if(!c)return Polynomial();Polynomial r(*c);if(!c->step()||a.zero()||b.zero())return r;if(a.degree()+b.degree()>64){c->numbers.fail(SA_INK_CAPACITY);return r;}r.coefficients.resize(a.coefficients.size()+b.coefficients.size()-1);for(uint32_t i=0;i<a.coefficients.size()&&r.valid();i++)for(uint32_t j=0;j<b.coefficients.size()&&r.valid();j++)r.coefficients[i+j]+=a[(int)i]*b[(int)j];r.trim();return r;}
inline Polynomial scale(const Polynomial&a,const Q&q){if(!a.owner())return Polynomial();Polynomial r(*a.owner());if(!a.owner()->step())return r;for(const auto&v:a.coefficients)r.coefficients.push_back(v*q);r.trim();return r;}
inline Q evaluate(const Polynomial&p,const Q&t){if(!p.owner())return Q();if(!p.owner()->step())return Q();Q s=Q::from_signed(p.owner()->numbers,0);for(int i=p.degree();i>=0&&p.valid();i--)s=s*t+p[i];return s;}
inline Polynomial derivative(const Polynomial&p){if(!p.owner())return Polynomial();Polynomial r(*p.owner());for(uint32_t i=1;i<p.coefficients.size();i++)r.coefficients.push_back(p[(int)i]*Q(i));r.trim();return r;}
struct PolynomialDivision {Polynomial quotient,remainder;};
inline PolynomialDivision divide(Polynomial a,const Polynomial&b){auto*c=poly_owner(a,b);if(!c)return{};Polynomial q(*c);if(!c->step())return{q,a};if(b.zero()){c->numbers.fail(SA_INK_RANGE);return{q,a};}if(a.degree()>=b.degree())q.coefficients.resize((uint32_t)(a.degree()-b.degree()+1));while(!a.zero()&&a.degree()>=b.degree()&&a.valid()){int d=a.degree()-b.degree();Q f=a[a.degree()]/b[b.degree()];q.coefficients[(uint32_t)d]=f;for(int j=0;j<=b.degree()&&a.valid();j++)a.coefficients[(uint32_t)(j+d)]-=f*b[j];a.trim();}q.trim();return{q,a};}
inline Polynomial exact_divide(const Polynomial&a,const Polynomial&b){auto result=divide(a,b);if(!result.remainder.zero()&&a.context())a.context()->fail(SA_INK_RANGE);return result.quotient;}
inline Polynomial monic(const Polynomial&p){if(p.zero())return p;return scale(p,Q(1)/p[p.degree()]);}
inline Polynomial primitive_integer(const Polynomial&p){if(p.zero())return p;auto&c=*p.owner();Integer common=Integer::from(c.numbers,1);for(const auto&q:p.coefficients){Integer g=Integer::gcd(common,q.denominator());common=(common/g)*q.denominator();if(common.bits()>32768){c.numbers.fail(SA_INK_CAPACITY);return Polynomial(c);}}
    Vector<Integer>values(c.numbers);Integer content=Integer::from(c.numbers,0);for(const auto&q:p.coefficients){Integer v=(common/q.denominator())*q.numerator();if(v.bits()>65536){c.numbers.fail(SA_INK_CAPACITY);return Polynomial(c);}values.push_back(v);content=Integer::gcd(content,v);}Polynomial r(c);for(const auto&v:values)r.coefficients.push_back(Q(v/content,Integer::from(c.numbers,1)));r.trim();return r;}
inline Polynomial positive_pseudo_remainder(Polynomial a,const Polynomial&source){a=primitive_integer(a);Polynomial b=primitive_integer(source);if(!a.owner())return a;auto&c=*a.owner();if(b.zero()){c.numbers.fail(SA_INK_RANGE);return Polynomial(c);}while(!a.zero()&&a.degree()>=b.degree()&&a.valid()){int shift=a.degree()-b.degree();Integer lead=a[a.degree()].numerator(),factor=b[b.degree()].numerator().absolute(),sign=Integer(b[b.degree()].sign());Vector<Integer>v(c.numbers);Integer content=Integer::from(c.numbers,0);for(int i=0;i<=a.degree()&&a.valid();i++){Integer z=a[i].numerator()*factor;if(i>=shift&&i-shift<=b.degree())z=z-lead*sign*b[i-shift].numerator();if(z.bits()>32770){c.numbers.fail(SA_INK_CAPACITY);return Polynomial(c);}v.push_back(z);content=Integer::gcd(content,z);}a=Polynomial(c);if(!content.zero())for(const auto&z:v)a.coefficients.push_back(Q(z/content,Integer::from(c.numbers,1)));a.trim();c.step();}return a;}
constexpr bool prime_modulus(uint32_t p){if(p<2)return false;if(!(p&1))return p==2;for(uint32_t d=3;uint64_t(d)*d<=p;d+=2)if(p%d==0)return false;return true;}
static_assert(prime_modulus(1000000007u)&&prime_modulus(1000000009u)&&prime_modulus(998244353u),"invalid exact-certificate modulus");
inline uint32_t modular_power(uint32_t a,uint32_t b,uint32_t p){uint64_t r=1;while(b){if(b&1)r=r*a%p;a=(uint32_t)(uint64_t(a)*a%p);b>>=1;}return(uint32_t)r;}
inline bool modular_coprime(const Polynomial&a,const Polynomial&b){if(!a.owner()||!b.owner())return false;auto&c=*a.owner();const uint32_t primes[3]={1000000007u,1000000009u,998244353u};for(uint32_t p:primes){Vector<uint32_t>A(c.numbers),B(c.numbers);auto convert=[&](const Polynomial&q,Vector<uint32_t>&out){for(const auto&x:q.coefficients){uint32_t den=x.denominator().mod_small(p);if(!den)return false;uint32_t v=(uint32_t)(uint64_t(x.numerator().mod_small(p))*modular_power(den,p-2,p)%p);out.push_back(v);}return!out.empty()&&out.back()!=0;};if(!convert(a,A)||!convert(b,B))continue;while(!B.empty()&&c.numbers.status==SA_INK_OK){uint32_t inverse=modular_power(B.back(),p-2,p);while(A.size()>=B.size()&&c.numbers.status==SA_INK_OK){uint32_t shift=A.size()-B.size(),f=(uint32_t)(uint64_t(A.back())*inverse%p);for(uint32_t i=0;i<B.size();i++)A[i+shift]=(uint32_t)((uint64_t(A[i+shift])+p-uint64_t(f)*B[i]%p)%p);while(!A.empty()&&A.back()==0)A.pop_back();c.step();}Vector<uint32_t>tmp=static_cast<Vector<uint32_t>&&>(A);A=static_cast<Vector<uint32_t>&&>(B);B=static_cast<Vector<uint32_t>&&>(tmp);}if(A.size()==1)return true;}return false;}
inline Polynomial gcd(Polynomial a,Polynomial b){auto*c=poly_owner(a,b);if(!c)return Polynomial();if(a.zero())return monic(b);if(b.zero())return monic(a);if(a.degree()==0||b.degree()==0||modular_coprime(a,b))return Polynomial::scalar(*c,1);a=primitive_integer(a);b=primitive_integer(b);while(!b.zero()&&a.valid()){Polynomial r=positive_pseudo_remainder(a,b);a=static_cast<Polynomial&&>(b);b=static_cast<Polynomial&&>(r);}return monic(a);}
inline Polynomial squarefree(const Polynomial&p){return p.zero()?p:monic(exact_divide(p,gcd(p,derivative(p))));}
inline Polynomial compose(const Polynomial&p,const Polynomial&t){auto*c=poly_owner(p,t);if(!c)return Polynomial();Polynomial q(*c);for(int i=p.degree();i>=0&&q.valid();i--)q=q*t+Polynomial(*c,p[i]);return q;}
struct Interval{Q lower,upper;};
inline Interval add(Interval a,Interval b){return{a.lower+b.lower,a.upper+b.upper};}inline Interval negate(Interval a){return{-a.upper,-a.lower};}
inline Interval multiply(Interval a,Interval b){Q v[4]={a.lower*b.lower,a.lower*b.upper,a.upper*b.lower,a.upper*b.upper};Q lo=v[0],hi=v[0];for(uint32_t i=1;i<4;i++){if(v[i]<lo)lo=v[i];if(v[i]>hi)hi=v[i];}return{lo,hi};}
inline Interval divide(Interval a,Interval b){if(b.lower<=Q(0)&&b.upper>=Q(0)){auto*c=b.lower.context()?b.lower.context():b.upper.context();if(c)c->fail(SA_INK_RANGE);return{};}return multiply(a,{Q(1)/b.upper,Q(1)/b.lower});}
inline Interval evaluate(const Polynomial&p,Interval t){Interval r{Q(0),Q(0)};for(int i=p.degree();i>=0&&p.valid();i--)r=add(multiply(r,t),{p[i],p[i]});return r;}
struct RationalFunction {Polynomial numerator,denominator;RationalFunction()=default;explicit RationalFunction(const Polynomial&p):numerator(p),denominator(p.owner()?Polynomial::scalar(*p.owner(),1):Polynomial()){}RationalFunction(Polynomial a,Polynomial b):numerator(static_cast<Polynomial&&>(a)),denominator(static_cast<Polynomial&&>(b)){normalize();}void normalize(){auto*c=poly_owner(numerator,denominator);if(!c)return;if(denominator.zero()){c->numbers.fail(SA_INK_RANGE);return;}if(numerator.zero()){denominator=Polynomial::scalar(*c,1);return;}auto g=gcd(numerator,denominator);numerator=exact_divide(numerator,g);denominator=exact_divide(denominator,g);Q leading=denominator[denominator.degree()];numerator=scale(numerator,Q(1)/leading);denominator=scale(denominator,Q(1)/leading);}};
inline RationalFunction sum(const RationalFunction&a,const RationalFunction&b,bool subtract){auto g=gcd(a.denominator,b.denominator),ad=exact_divide(a.denominator,g),bd=exact_divide(b.denominator,g);auto n=a.numerator*bd+(subtract?-(b.numerator*ad):b.numerator*ad);auto cancel=gcd(n,g);return{exact_divide(n,cancel),ad*exact_divide(b.denominator,cancel)};}
inline RationalFunction operator+(const RationalFunction&a,const RationalFunction&b){return sum(a,b,false);}inline RationalFunction operator-(const RationalFunction&a,const RationalFunction&b){return sum(a,b,true);}
inline RationalFunction operator*(const RationalFunction&a,const RationalFunction&b){auto g=gcd(a.numerator,b.denominator),h=gcd(b.numerator,a.denominator);return{exact_divide(a.numerator,g)*exact_divide(b.numerator,h),exact_divide(a.denominator,h)*exact_divide(b.denominator,g)};}
inline RationalFunction operator/(const RationalFunction&a,const RationalFunction&b){auto g=gcd(a.numerator,b.numerator),h=gcd(b.denominator,a.denominator);return{exact_divide(a.numerator,g)*exact_divide(b.denominator,h),exact_divide(a.denominator,h)*exact_divide(b.numerator,g)};}
inline RationalFunction substitute(const Polynomial&p,const RationalFunction&t){if(!p.owner())return{};RationalFunction r{Polynomial(*p.owner())};for(int i=p.degree();i>=0&&p.valid();i--)r=r*t+RationalFunction(Polynomial(*p.owner(),p[i]));return r;}
using PolynomialSequence=Vector<Polynomial,1>;
struct Root {
    Record<Polynomial>definition_record;Q lower,upper;Record<PolynomialSequence>sequence;
    Root()=default;
    Root(const Polynomial&p,Q a,Q b):definition_record(p.context()?Record<Polynomial>::create(*p.context(),p):Record<Polynomial>()),lower(p.context()?a.owned(*p.context()):a),upper(p.context()?b.owned(*p.context()):b){}
    Root(Record<Polynomial>p,Q a,Q b,Record<PolynomialSequence>s):definition_record(static_cast<Record<Polynomial>&&>(p)),lower(context()?a.owned(*context()):a),upper(context()?b.owned(*context()):b),sequence(static_cast<Record<PolynomialSequence>&&>(s)){}
    Context*context()const{return definition_record.context();}bool valid()const{return definition_record.valid()&&context()->status==SA_INK_OK;}const Polynomial&definition()const{return*definition_record.get();}bool exact()const{return lower==upper;}Q midpoint()const{return(lower+upper)/Q(2);}
};
static_assert(sizeof(Root)==128,"portable root layout");
inline PolynomialSequence sturm(const Polynomial&p){if(!p.owner())return{};auto&c=*p.owner();PolynomialSequence r(c.numbers);r.push_back(primitive_integer(p));r.push_back(primitive_integer(derivative(p)));while(!r.back().zero()&&p.valid()){auto next=-positive_pseudo_remainder(r[r.size()-2],r.back());if(next.zero())break;r.push_back(next);}if(!r.empty()&&r.back().zero())r.pop_back();return r;}
inline int side_sign(Polynomial p,const Q&x,int side){uint32_t order=0;while(!p.zero()&&p.valid()){Q v=evaluate(p,x);if(!v.zero())return v.sign()*((order&1)?side:1);p=derivative(p);++order;}return 0;}
inline int variations(const PolynomialSequence&sequence,const Q&x,int side){int previous=0,count=0;for(const auto&p:sequence){int next=side_sign(p,x,side);if(next){if(previous&&previous!=next)++count;previous=next;}}return count;}
inline int count_open(const PolynomialSequence&sequence,const Q&a,const Q&b){return a<b?variations(sequence,a,1)-variations(sequence,b,-1):0;}
inline const PolynomialSequence*chain(Root&r){if(!r.valid())return nullptr;if(!r.sequence.valid())r.sequence=Record<PolynomialSequence>::create(*r.context(),sturm(r.definition()));return r.sequence.get();}
inline void refine(Root&r){if(!r.valid()||r.exact())return;Q mid=r.midpoint();if(evaluate(r.definition(),mid).zero()){r.lower=r.upper=mid;return;}const auto*s=chain(r);if(!s)return;if(count_open(*s,r.lower,mid))r.upper=mid;else r.lower=mid;}
struct IsolationFrame{Q a,b;int count=0;uint32_t depth=0;Context*context()const{return a.context()?a.context():b.context();}};
inline void isolate(const Record<Polynomial>&definition,const Record<PolynomialSequence>&sequence,const Q&a,const Q&b,int count,Vector<Root>&out,uint32_t depth){if(!definition.valid()||!sequence.valid())return;const auto&p=*definition.get();Vector<IsolationFrame,1>pending(*p.context());pending.push_back({a,b,count,depth});Q width(Integer::from(*p.context(),1),Integer::from(*p.context(),1).shifted_left(56));while(!pending.empty()&&p.valid()){IsolationFrame f=pending.back();pending.pop_back();if(!f.count)continue;if(f.depth>256){p.context()->fail(SA_INK_RANGE);return;}if(f.count==1&&f.b-f.a<width&&!evaluate(p,f.a).zero()&&!evaluate(p,f.b).zero()&&p.valid()){out.push_back(Root(definition,f.a,f.b,sequence));continue;}Q mid=(f.a+f.b)/Q(2);if(evaluate(p,mid).zero())out.push_back(Root(definition,mid,mid,sequence));int left=count_open(*sequence.get(),f.a,mid),right=count_open(*sequence.get(),mid,f.b);if(right)pending.push_back({mid,f.b,right,f.depth+1});if(left)pending.push_back({f.a,mid,left,f.depth+1});if(pending.size()>257){p.context()->fail(SA_INK_CAPACITY);return;}}}
inline Vector<Root> roots(const Polynomial&source){if(!source.owner())return{};auto&c=*source.owner();Vector<Root>r(c.numbers);Polynomial p=squarefree(source);if(p.degree()<=0||!p.valid())return r;auto definition=Record<Polynomial>::create(c.numbers,p);if(!definition.valid())return r;if(p.degree()==1){Q x=-p[0]/p[1];if(x>=Q(0)&&x<=Q(1))r.push_back(Root(definition,x,x,{}));return r;}auto sequence=Record<PolynomialSequence>::create(c.numbers,sturm(p));if(!sequence.valid())return r;Q zero=Q::from_signed(c.numbers,0),one=Q::from_signed(c.numbers,1);if(evaluate(p,zero).zero())r.push_back(Root(definition,zero,zero,sequence));if(evaluate(p,one).zero())r.push_back(Root(definition,one,one,sequence));isolate(definition,sequence,zero,one,count_open(*sequence.get(),zero,one),r,0);for(uint32_t i=1;i<r.size()&&p.valid();i++){Root x=r[i];uint32_t j=i;while(j&&x.lower<r[j-1].lower){r[j]=r[j-1];--j;}r[j]=x;}return r;}
inline bool root_of(const Root&r,const Polynomial&p){if(!r.valid())return false;if(p.zero())return true;if(r.exact())return evaluate(p,r.lower).zero();auto v=evaluate(p,{r.lower,r.upper});if(v.lower>Q(0)||v.upper<Q(0))return false;auto g=gcd(r.definition(),p);auto s=sturm(g);return count_open(s,r.lower,r.upper)>0||evaluate(g,r.lower).zero()||evaluate(g,r.upper).zero();}
inline bool same_root(Root&a,Root&b){if(!a.valid()||!b.valid())return false;if(a.upper<b.lower||b.upper<a.lower)return false;if(a.exact()&&b.exact())return a.lower==b.lower;auto g=gcd(a.definition(),b.definition());auto s=sturm(g);for(uint32_t i=0;i<256&&g.valid();i++){if(a.upper<b.lower||b.upper<a.lower)return false;if(a.exact()&&b.exact())return a.lower==b.lower;Q lo=a.lower>b.lower?a.lower:b.lower,hi=a.upper<b.upper?a.upper:b.upper;if(g.degree()>0&&(count_open(s,lo,hi)||evaluate(g,lo).zero()||evaluate(g,hi).zero()))return true;refine(a);refine(b);}if(g.context())g.context()->fail(SA_INK_RANGE);return false;}
inline Polynomial resultant(const Vector<Polynomial>&p,const Vector<Polynomial>&q){PolynomialContext*c=!p.empty()?p[0].owner():!q.empty()?q[0].owner():nullptr;if(!c)return{};int m=(int)p.size()-1,n=(int)q.size()-1,N=m+n;if(m<0||n<0)return Polynomial(*c);if(N==0)return Polynomial::scalar(*c,1);if(N>6){c->numbers.fail(SA_INK_CAPACITY);return Polynomial(*c);}Vector<Vector<Polynomial>>matrix(c->numbers);matrix.resize((uint32_t)N);for(int i=0;i<N;i++){matrix[(uint32_t)i]=Vector<Polynomial>(c->numbers);matrix[(uint32_t)i].resize((uint32_t)N);for(int j=0;j<N;j++)matrix[(uint32_t)i][(uint32_t)j]=Polynomial(*c);}for(int i=0;i<n;i++)for(int j=0;j<=m;j++)matrix[(uint32_t)i][(uint32_t)(i+j)]=p[(uint32_t)(m-j)];for(int i=0;i<m;i++)for(int j=0;j<=n;j++)matrix[(uint32_t)(n+i)][(uint32_t)(i+j)]=q[(uint32_t)(n-j)];Polynomial previous=Polynomial::scalar(*c,1);int sign=1;for(int k=0;k<N-1&&c->numbers.status==SA_INK_OK;k++){int pivot=k;while(pivot<N&&matrix[(uint32_t)pivot][(uint32_t)k].zero())++pivot;if(pivot==N)return Polynomial(*c);if(pivot!=k){auto row=static_cast<Vector<Polynomial>&&>(matrix[(uint32_t)pivot]);matrix[(uint32_t)pivot]=static_cast<Vector<Polynomial>&&>(matrix[(uint32_t)k]);matrix[(uint32_t)k]=static_cast<Vector<Polynomial>&&>(row);sign=-sign;}Polynomial d=matrix[(uint32_t)k][(uint32_t)k];for(int i=k+1;i<N&&c->numbers.status==SA_INK_OK;i++)for(int j=k+1;j<N&&c->numbers.status==SA_INK_OK;j++)matrix[(uint32_t)i][(uint32_t)j]=exact_divide(matrix[(uint32_t)i][(uint32_t)j]*d-matrix[(uint32_t)i][(uint32_t)k]*matrix[(uint32_t)k][(uint32_t)j],previous);for(int i=k+1;i<N;i++)matrix[(uint32_t)i][(uint32_t)k]=Polynomial(*c);previous=d;}return scale(matrix[(uint32_t)(N-1)][(uint32_t)(N-1)],Q(sign));}
}
#endif
